import math
from collections import defaultdict

class HybridSearch:
    def __init__(self):
        self.docs = {}

    def add(self, id, vector, text):
        self.docs[id] = {"vector": vector, "text": text}

    def cosine(self, a, b):
        d = sum(x * y for x, y in zip(a, b))
        ma = math.sqrt(sum(x * x for x in a))
        mb = math.sqrt(sum(x * x for x in b))
        return d / (ma * mb) if ma and mb else 0.0

    def vector_search(self, query_vec, k=3):
        scored = [(id, self.cosine(query_vec, d["vector"])) for id, d in self.docs.items()]
        return [id for id, _ in sorted(scored, key=lambda x: -x[1])[:k]]

    def keyword_search(self, query_terms, k=3):
        scored = []
        for id, d in self.docs.items():
            hits = sum(1 for t in query_terms if t.lower() in d["text"].lower())
            scored.append((id, hits))
        return [id for id, _ in sorted(scored, key=lambda x: -x[1]) if _ > 0][:k]

    def hybrid(self, query_vec, query_terms, k=3):
        v = self.vector_search(query_vec, k * 2)
        w = self.keyword_search(query_terms, k * 2)
        # Reciprocal rank fusion
        scores = defaultdict(float)
        for ranks in [v, w]:
            for rank, id in enumerate(ranks):
                scores[id] += 1 / (60 + rank + 1)
        return sorted(scores.items(), key=lambda x: -x[1])[:k]

hs = HybridSearch()
hs.add("doc1", [0.9, 0.1], "All about machine learning")
hs.add("doc2", [0.85, 0.15], "Deep learning transformers")
hs.add("doc3", [0.1, 0.9], "Financial reports 2023")
hs.add("doc4", [0.7, 0.3], "Neural networks overview")

results = hs.hybrid([0.88, 0.12], ["learning", "neural"], k=2)
print("Hybrid results:", results)
